// Articles page (generated by scripts/gen_articles.py).
// Pointing at (or focusing) an article highlights it and puts its card, a <template> after
// the list, in the column on the right. Leaving the list puts the card back to its overview;
// the card stays while the pointer is on the card itself, so its links can be used.
// Entries in the card that point to another article on the page select it.
document$.subscribe(function () {
  var wrap = document.querySelector(".rm-ar-wrap");
  if (!wrap || wrap.dataset.ready) return;
  wrap.dataset.ready = "1";
  var main = wrap.querySelector(".rm-ar-main");
  var card = wrap.querySelector(".rm-ar-card");
  var rows = Array.prototype.slice.call(wrap.querySelectorAll(".rm-ar"));
  if (!card || !rows.length) return;
  var cur = null, timer = null;

  function fill(id) {
    var tpl = document.getElementById(id);
    if (!tpl) return;
    card.innerHTML = "";
    card.appendChild(tpl.content.cloneNode(true));
    // an entry for an article without its own page (a placeholder) selects it in the list
    card.querySelectorAll("[data-go]:not([href])").forEach(function (n) {
      n.setAttribute("tabindex", "0");
      n.addEventListener("click", function () { go(+n.dataset.go); });
      n.addEventListener("keydown", function (e) { if (e.key === "Enter") go(+n.dataset.go); });
    });
  }
  function go(i) {
    var row = rows.filter(function (r) { return +r.dataset.card === i; })[0];
    if (!row) return;
    row.scrollIntoView({ behavior: "smooth", block: "center" });
    select(row);
  }
  function select(row) {
    if (cur === row) return;
    cur = row;
    rows.forEach(function (r) { r.classList.toggle("is-on", r === row); });
    fill("rm-arc-" + row.dataset.card);
  }
  function rest() {
    cur = null;
    rows.forEach(function (r) { r.classList.remove("is-on"); });
    fill("rm-arc-idle");
  }
  rows.forEach(function (r) {
    r.addEventListener("mouseenter", function () { clearTimeout(timer); timer = setTimeout(function () { select(r); }, 60); });
    r.addEventListener("focus", function () { select(r); });
  });
  main.addEventListener("mouseleave", function (e) { clearTimeout(timer); if (!card.contains(e.relatedTarget)) rest(); });
  card.addEventListener("mouseleave", function (e) { if (!main.contains(e.relatedTarget)) rest(); });
  rest();
});
